tape( 'the function joins elements and assigns results to an output ndarray (default, row-major)', function test( t ) {
	var expected;
	var actual;
	var xbuf;
	var out;
	var x;

	xbuf = [ 1.0, 2.0, 3.0, 4.0 ];
	x = new ndarray( 'generic', xbuf, [ 2, 2 ], [ 2, 1 ], 0, 'row-major' );
	out = empty( [], {
		'dtype': 'generic'
	});

	actual = joinBetween( x, out );
	expected = '1,2,3,4';

	t.strictEqual( isndarrayLike( actual ), true, 'returns expected value' );
	t.strictEqual( getDType( actual ), 'generic', 'returns expected value' );
	t.deepEqual( getShape( actual ), [], 'returns expected value' );
	t.strictEqual( getOrder( actual ), getOrder( x ), 'returns expected value' );
	t.deepEqual( actual.get(), expected, 'returns expected value' );
	t.strictEqual( actual, out, 'returns expected value' );

	t.end();
});

tape( 'the function supports specifying reduction dimensions (row-major)', function test( t ) {
	var expected;
	var actual;
	var xbuf;
	var out;
	var x;

	xbuf = [ 1.0, 2.0, 3.0, 4.0 ];
	x = new ndarray( 'generic', xbuf, [ 2, 2 ], [ 2, 1 ], 0, 'row-major' );
	out = zeros( [ 2 ], {
		'dtype': 'generic'
	});

	actual = joinBetween( x, out, {
		'dims': [ 0 ]
	});
	expected = [ '1,3', '2,4' ];

	t.strictEqual( isndarrayLike( actual ), true, 'returns expected value' );
	t.deepEqual( getShape( actual ), [ 2 ], 'returns expected value' );
	t.deepEqual( ndarray2array( actual ), expected, 'returns expected value' );
	t.strictEqual( actual, out, 'returns expected value' );

	xbuf = [ 1.0, 2.0, 3.0, 4.0 ];
	x = new ndarray( 'generic', xbuf, [ 2, 2 ], [ 2, 1 ], 0, 'row-major' );
	out = zeros( [ 2 ], {
		'dtype': 'generic'
	});

	actual = joinBetween( x, out, {
		'dims': [ 1 ]
	});
	expected = [ '1,2', '3,4' ];

	t.strictEqual( isndarrayLike( actual ), true, 'returns expected value' );
	t.deepEqual( getShape( actual ), [ 2 ], 'returns expected value' );
	t.deepEqual( ndarray2array( actual ), expected, 'returns expected value' );
	t.strictEqual( actual, out, 'returns expected value' );

	t.end();
});

tape( 'the function supports specifying a prefix and suffix', function test( t ) {
	var expected;
	var actual;
	var xbuf;
	var out;
	var x;

	xbuf = [ 1.0, 2.0, 3.0, 4.0 ];
	x = new ndarray( 'generic', xbuf, [ 2, 2 ], [ 2, 1 ], 0, 'row-major' );
	out = zeros( [ 2 ], {
		'dtype': 'generic'
	});

	actual = joinBetween( x, out, {
		'dims': [ 1 ],
		'prefix': '[ ',
		'suffix': ' ]',
		'separators': [ ', ' ]
	});
	expected = [ '[ 1, 2 ]', '[ 3, 4 ]' ];

	t.strictEqual( isndarrayLike( actual ), true, 'returns expected value' );
	t.deepEqual( ndarray2array( actual ), expected, 'returns expected value' );
	t.strictEqual( actual, out, 'returns expected value' );

	t.end();
});

tape( 'the function supports per-pair separators via an array', function test( t ) {
	var expected;
	var actual;
	var xbuf;
	var out;
	var x;

	xbuf = [ 1.0, 2.0, 3.0, 4.0 ];
	x = new ndarray( 'generic', xbuf, [ 4 ], [ 1 ], 0, 'row-major' );
	out = empty( [], {
		'dtype': 'generic'
	});

	actual = joinBetween( x, out, {
		'separators': [ ' + ', ' - ', ' != ' ],
		'prefix': 'op: ',
		'suffix': ''
	});
	expected = 'op: 1 + 2 - 3 != 4';

	t.strictEqual( isndarrayLike( actual ), true, 'returns expected value' );
	t.deepEqual( actual.get(), expected, 'returns expected value' );
	t.strictEqual( actual, out, 'returns expected value' );

	t.end();
});
